solution:
use xiom.io;

use xiom.string;
module models {
  pub type Product = { name: Str; price: Int; stock: Int; }
}

module inventory {
  pub fn is_in_stock(product: &models.Product) -> Bool {
    return product.stock > 0;
  }
}

module formatting {
  pub fn format_price(price: Int) -> Str {
    return "$" + to_string(price);
  }
}

module pricing {
  pub fn apply_sale(price: Int) -> Int {
    return price * 80 / 100;
  }
}

fn main() -> Int {
  let product = models.Product{ name: "Widget", price: 100, stock: 5 };
  if inventory.is_in_stock(&product) {
    let sale_price = pricing.apply_sale(product.price);
    io.println(formatting.format_price(sale_price));
  }
  return 0;
}
